// Standard questions, ccarf. Original items written against the published exam guide. Built from content/en by tools/build-en.js.
window.QUESTIONS = window.QUESTIONS || {};
window.QUESTIONS.ccarf = [
// ---- Domain 1 ----
{ id:'ccarf-1-01', d:1, o:0, s:1, q:"In a customer support agent's loop, a developer wrote “stop when the response text contains ‘resolved’”. In production the loop sometimes ends while the model is still asking for a tool call. Which fix is correct?",
  c:["Keep running tools and returning results while it is `tool_use`, and end the loop on `end_turn`", "Widen the stop keywords to “done”, “handled” and “that is all”, so fewer endings go undetected", "Add a cap so the loop always ends after at most 3 exchanges, whether or not a tool is requested", "End only when the response text is empty, and keep going for as long as any prose comes back"],
  a:[0], e:"The loop ends on stop_reason. Detecting natural language, fixed counts and checking for text are all anti-patterns." },
{ id:'ccarf-1-02', d:1, o:0, s:1, q:"Which is correct when handling tool results in an agentic loop?",
  c:["Add each tool result to the conversation history before the next call, so the model can act on the new information", "Keep tool results out of history and append only a summary to the system prompt, to stop the history growing", "Have a developer read each tool result and write the next instruction by hand, without passing the raw data on", "Fix the order of tools with a decision tree up front, and branch on results in code rather than in the model"],
  a:[0], e:"Model-driven decisions depend on the results being in history. A decision tree fixed in advance gives up the agent's value, which is that the model decides what comes next." },
{ id:'ccarf-1-03', d:1, o:0, s:4, q:"An agent might keep calling tools forever. Which design is a sound safety valve that does not undermine the main stop condition?",
  c:["Make `end_turn` the main stop, and add a cap (count, time) as a backstop for abnormal cases", "Make a count cap the only stop condition, and halt at that count without reading `stop_reason`", "Allow the tool to be used only once, and treat a second tool request as the end of the loop", "Ask the model to “finish within 3 exchanges”, and leave the decision to stop up to the model"],
  a:[0], e:"A count cap as the main stop mechanism is an anti-pattern, but it is reasonable as a backstop against runaway loops." },
{ id:'ccarf-1-04', d:1, o:1, s:3, q:"In a research system, someone proposes that the search subagent pass its results straight to the document analysis subagent. What is the problem, measured against the recommended structure?",
  c:["Subagents should talk through the coordinator (hub and spoke); direct links weaken observability, error handling and control of flow", "Direct links skip the coordinator and so are always faster; on latency grounds there is no problem and they are the preferred design", "Subagents have no means of talking to one another, so a direct link cannot be built and the proposal needs no further thought", "There is none. If subagents can exchange information directly, the coordinator carries less load and the overall cost comes down"],
  a:[0], e:"The recommended structure has the coordinator own all communication, error handling and routing." },
{ id:'ccarf-1-05', d:1, o:1, s:3, q:"The coordinator runs the full “search → analyze → synthesize → report” pipeline every time, so even simple questions are slow and costly. Which improvement fits?",
  c:["The coordinator assesses the question's complexity and calls only the subagents it needs", "Keep the pipeline fixed and switch each of the subagents to a faster and cheaper model", "Merge the subagents into one agent that does everything from search to synthesis in turn", "Tell users not to ask simple questions, and accept only complex ones that suit the system"],
  a:[0], e:"Delegating dynamically according to the query is the coordinator's job." },
{ id:'ccarf-1-06', d:1, o:1, s:3, q:"The synthesis subagent's output has gaps. Which coordinator design is appropriate?",
  c:["Assess the gaps in the synthesis, re-delegate targeted work for what is missing, and rerun synthesis until it is sufficient", "Move the synthesis agent to a higher model, and expect a more complete synthesis to come out of the very same input", "Output it as it is without noting the gaps, and leave it to the user to read it and ask about whatever is missing", "Start over from the first search, rerun every one of the subagents, and rebuild the synthesis from the new results"],
  a:[0], e:"An iterative refinement loop (assess → re-delegate → re-synthesize) is the recommended pattern." },
{ id:'ccarf-1-07', d:1, o:1, s:3, q:"The coordinator broke the broad topic “economic impact of climate change” down into just “impact of carbon taxes”, and the report came out lopsided. What is the cause?",
  c:["Task decomposition by the coordinator that is too narrow. For a broad topic, divide the work by subtopic or source type without overlap", "There are too many subagents, so several of them hit the same sources at the same time and their results overlap one another", "The model lacks knowledge and does not know the sources on the topic, so it keeps finding the same small handful of sources", "There are too few kinds of search tool, so every subagent uses the same tool and can only ever retrieve the same results"],
  a:[0], e:"Decomposition that is too narrow lowers coverage. Designing how the scope is divided is the coordinator's responsibility." },
{ id:'ccarf-1-08', d:1, o:2, s:3, q:"The synthesis subagent answers “I cannot find any search results”. The search subagent is working normally. What is the most likely cause?",
  c:["Subagents do not inherit the parent's context, and the search results were not put explicitly into the synthesis agent's prompt", "The model used for the synthesis agent is old, and is not capable of reading long search results and synthesizing them", "The search results and the instructions are in different languages, so it skips the results and writes from its own knowledge", "The synthesis agent has no Task tool, so it cannot call the search subagent itself in order to fetch the results"],
  a:[0], e:"A subagent's context is isolated; the information it needs goes directly into its prompt." },
{ id:'ccarf-1-09', d:1, o:2, s:4, q:"The coordinator cannot launch subagents. What should you check in its `allowedTools`?",
  c:["Whether the coordinator's `allowedTools` includes `Task`", "Whether the coordinator's `allowedTools` includes `Bash`", "Whether `allowedTools` was left empty to allow every tool", "Whether the subagent's model name is set to the latest one"],
  a:[0], e:"Subagents are spawned through the Task tool, so allowedTools needs Task." },
{ id:'ccarf-1-10', d:1, o:2, s:3, q:"You want to investigate three sources at the same time. Which coordinator implementation is most efficient?",
  c:["Emit several Task tool calls in one response, launching the subagents in parallel", "Launch one per turn in order, reading each subagent's result before the next", "Use no subagents; the coordinator checks the three sources itself, one by one", "Have a person start three sessions by hand and paste each result to the coordinator"],
  a:[0], e:"Parallelism comes from several Task calls in a single response." },
{ id:'ccarf-1-11', d:1, o:2, s:3, q:"When passing context to a subagent, which design keeps source information intact?",
  c:["Pass a structured format that separates content from metadata (URL, document name, page)", "Join everything into one long passage, with the sources embedded naturally in the body text", "Leave sources out of the body, and state them all together at the end as a loose list", "Drop the metadata and pass only the body of the content, to lighten the synthesis agent's load"],
  a:[0], e:"Structuring the context and separating content from metadata preserves attribution downstream." },
{ id:'ccarf-1-12', d:1, o:2, s:3, q:"Which way of writing the coordinator's prompt to a subagent is recommended?",
  c:["State the research goal and quality criteria, and leave the detailed steps to the subagent", "Specify the procedure one step at a time, leaving the subagent no room for judgment", "Leave the prompt empty and let it work freely, trusting the subagent's judgment entirely", "Paste in the parent's entire history, so the subagent shares all of the context as it works"],
  a:[0], e:"Giving goals and criteria without fixing the steps lets the subagent adapt to what it finds." },
{ id:'ccarf-1-13', d:1, o:3, s:1, q:"In production, the agent skips `get_customer` and calls `process_refund`, refunding the wrong account in 12% of cases. Which measure is most effective?",
  c:["Add a programmatic gate so `lookup_order` and `process_refund` cannot be called until `get_customer` returns a verified customer ID", "Stress in the system prompt: “always call get_customer first and confirm the customer before any order lookup or refund”", "Add more few-shot examples of the right order (get_customer → lookup_order → process_refund) so the model learns it", "Add a router that enables tools by request type, so the refund tool is switched on only for refund enquiries"],
  a:[0], e:"Enforce an order that involves money programmatically. A prompt is probabilistic, and its failure rate never reaches zero." },
{ id:'ccarf-1-14', d:1, o:3, s:1, q:"A customer says all at once: “I want to return something. My bill is wrong too. And I cannot log in to my account.” Which handling design is appropriate?",
  c:["Break it into three separate issues, investigate them in parallel under shared context, then merge them into one unified reply", "Deal with the first issue only and reply to that, then wait for the customer to get in touch again about the other two", "Treat the three as one mixed problem, investigate them all together, and explain them as having one single cause", "Because three tangled issues are complex, escalate all of it to a human agent without investigating anything first"],
  a:[0], e:"Decompose multiple concerns → investigate in parallel → synthesize is the recommended pattern." },
{ id:'ccarf-1-15', d:1, o:3, s:1, q:"When escalating to a human agent, the agent cannot see the conversation transcript. What should the handoff contain?",
  c:["A structured summary with the customer ID, root cause analysis, refund amount and recommended action", "A short message that holds only the words “please take care of this” and the customer's name", "The full conversation pasted in as is, for the agent to read from the start and work out the situation", "Only an analysis of the customer's sentiment, leaving the agent to ask again about the facts"],
  a:[0], e:"A structured handoff (customer ID, root cause, amount, recommended action) is the requirement." },
{ id:'ccarf-1-16', d:1, o:4, s:1, q:"Several MCP tools return dates and times as Unix timestamps, ISO 8601 and custom formats, and the agent compares them wrongly. Which measure fits best?",
  c:["Normalize tool results in a PostToolUse hook before they reach the model", "Write in the system prompt: “take care over differing date formats”", "Cut the number of tools that return dates until one format is left", "Stop comparing dates, and ask the user to confirm the order instead"],
  a:[0], e:"A PostToolUse hook is used to transform tool results." },
{ id:'ccarf-1-17', d:1, o:4, s:1, q:"Policy says “refunds over $500 need human approval”. Which approach makes sure it is kept?",
  c:["A hook blocks any `process_refund` over the threshold and routes it to human escalation", "Put the threshold in the system prompt, with “escalate refunds above it to a person”", "Show few-shot examples of over-threshold refunds being escalated, so the model learns", "Move to a higher model so it keeps the threshold instruction more reliably than before"],
  a:[0], e:"Dependable compliance with a business rule comes from a hook, which is deterministic." },
{ id:'ccarf-1-18', d:1, o:4, s:1, q:"Which correctly divides “enforcement by hook” from “instruction by prompt”?",
  c:["Hooks for rules that need a guarantee; prompts for behavior that needs flexible judgment", "Implement everything as hooks, and write no behavioral rules in the prompt at all", "Implement everything in the prompt, and use hooks only for logging what was executed", "There is no difference; either one controls behavior with the same degree of certainty"],
  a:[0], e:"Know the difference between a deterministic guarantee and probabilistic compliance, and choose accordingly." },
{ id:'ccarf-1-19', d:1, o:5, s:5, q:"In CI, reviewing a 30-file PR in a single pass spreads attention thin and yields contradictory comments. Which improvement fits?",
  c:["Split it into a local review pass for each file and a cross-file integration pass (prompt chaining)", "Keep every file in one giant prompt, and switch to a higher model in order to raise the accuracy", "Stop the automated review, and handle large PRs through human review alone from now on", "Order the files from the largest change down, so the important files are read first"],
  a:[0], e:"A predictable, multi-aspect review is split up with prompt chaining." },
{ id:'ccarf-1-20', d:1, o:5, s:4, q:"Which is a sound decomposition of the open-ended task “add comprehensive tests to a legacy codebase”?",
  c:["Map the structure first, identify high-impact areas, and make a prioritized plan that adapts as dependencies are discovered", "Apply the same fixed steps (read, fix, test) to every file in order, going ahead mechanically without making any plan", "Finish the migration without writing tests, and have people check the behavior in one go once all of it is done", "Rewrite everything in order from the first file, and deal with the dependencies whenever they break along the way"],
  a:[0], e:"An open-ended investigative task suits dynamic decomposition, where subtasks are generated from what is discovered." },
{ id:'ccarf-1-21', d:1, o:5, s:2, q:"What is the criterion for choosing between a fixed prompt chain and dynamic decomposition?",
  c:["A chain when the steps are predictable and multi-aspect; dynamic decomposition for open-ended tasks where findings change the next step", "Always a prompt chain for every kind of task, fixing the steps in advance and putting predictability ahead of everything else", "Always dynamic decomposition for every kind of task, leaving it to the model's judgment and putting flexibility ahead of all else", "Estimate both, and choose whichever has the lower API cost, without treating the nature of the task as an input to the decision"],
  a:[0], e:"Predictable steps suit a chain; work that changes with what you find suits dynamic decomposition." },
{ id:'ccarf-1-22', d:1, o:6, s:2, q:"You want to resume last week's investigation session, but the code has changed a lot since then. How should you resume?",
  c:["Tell it which files changed and have it re-analyze. If most earlier results are stale, start a new session from a structured summary", "Just `--resume` without saying anything, leaving the model to notice for itself where earlier results and the current code differ", "Carry on trusting the earlier tool results as correct, and fix the parts that have changed when they turn up during the work", "Always have it re-explore every file from the very beginning, and redo the analysis from zero without the earlier session"],
  a:[0], e:"Resume when the context is still mostly valid. When many results are stale, a fresh start from a summary is more reliable." },
{ id:'ccarf-1-23', d:1, o:6, s:2, q:"You want to compare “two testing strategies” on top of the same codebase analysis. Which feature fits?",
  c:["Use `fork_session` to branch from the shared analysis, and try one strategy on each branch", "Try both strategies in one session in turn, the second building on the results of the first", "Create two new sessions, and redo the analysis from zero in each before trying a strategy", "Two strategies cannot be compared on equal terms, so try just one of them and decide"],
  a:[0], e:"A fork is for exploring in different directions from a shared baseline." },
{ id:'ccarf-1-24', d:1, o:6, s:2, q:"Which option resumes a specific past session by name?",
  c:["Resume it with `--resume <session name>`", "Resume it with `--new <session name>`", "Resume it with `--fork <session name>`", "Resume it with `--print <session name>`"],
  a:[0], e:"A named session is resumed with --resume." },

// ---- Domain 2 ----
{ id:'ccarf-2-01', d:2, o:0, s:1, q:"`get_customer` (description: “Gets customer information”) and `lookup_order` (description: “Gets order details”) accept similar ID formats, and the agent picks the wrong one. Which first step is most effective?",
  c:["Add to each tool's description the input formats it handles, example queries, edge cases and when to use it rather than the similar tool", "Add 5 to 8 few-shot examples to the system prompt, each one showing which tool was used for which kind of customer enquiry", "Build a routing layer that picks tools by keyword in advance, narrowing the tools the model is given for each enquiry", "Merge the two tools into one `lookup_entity` tool, which switches between the two kinds of lookup by the argument type"],
  a:[0], e:"The tool description is the main cue for selection, so the first move is to enrich the descriptions." },
{ id:'ccarf-2-02', d:2, o:0, s:3, q:"`analyze_content` and `analyze_document` have nearly identical descriptions, and calls are misrouted. Which response fits?",
  c:["Change the names and descriptions to remove the overlap (if one is web only, give it a web-specific name and description)", "Delete both tools, and have the model do the extraction directly from system prompt instructions with no tool at all", "Shorten both descriptions further to make the difference stand out, so the model decides which to use from the name", "Leave the tools as they are, let the model decide which one to use, and absorb any wrong picks in post-processing"],
  a:[0], e:"Remove the overlap through naming and descriptions." },
{ id:'ccarf-2-03', d:2, o:0, s:3, q:"A generic `analyze_document` tool does data extraction, summarizing and claim verification all at once, and its output is unstable. Which improvement fits?",
  c:["Split it into purpose-built tools (extract, summarize, verify) and define the input and output contract of each", "Keep the one tool, and add how to use each of the three purposes plus input and output examples to its description", "Remove the tool and do extraction, summary and verification by prompt instruction alone, with the format specified there", "Move to a higher model, so it interprets the arguments of the one generic tool and shapes its results accurately"],
  a:[0], e:"Split a generic tool by purpose and make the input and output contracts explicit." },
{ id:'ccarf-2-04', d:2, o:0, s:1, q:"The tool descriptions were fine, but the wrong tool was being chosen because of one system prompt line: “Start every order enquiry from the customer record.” Which lesson is correct?",
  c:["Keyword-sensitive instructions in the system prompt can override well-written tool descriptions. Inspect the prompt as well", "Tool descriptions hardly affect what the model selects, so renaming the tools works better than fixing descriptions", "The system prompt should be empty; unless tool descriptions alone say which to use, conflicts cause wrong selections", "It is a fault on the model side, which misreads tool descriptions. Change the version, or report it and wait for a fix"],
  a:[0], e:"The wording of the system prompt affects tool selection." },
{ id:'ccarf-2-05', d:2, o:1, s:1, q:"An MCP tool returns only “Operation failed” for every failure, and the agent wastes retries on the same call. Which improvement fits?",
  c:["Along with `isError`, return a structured error: the error type, `isRetryable` and a human-readable explanation", "On an error return an empty success, so the model treats it as “no results”, and keep the detail in server logs only", "On an error stop the whole workflow and return nothing to the model; a person reads the logs and then reruns it", "Forbid retries, so a tool that fails on the first call can never be called again in that session, to prevent runaways"],
  a:[0], e:"With structured error metadata, the agent can judge whether to retry and what alternative to take." },
{ id:'ccarf-2-06', d:2, o:1, s:1, q:"A refund was rejected as a policy violation (past the deadline). Which MCP tool response is appropriate?",
  c:["Include `retriable: false` and an explanation that can be given to the customer (past the deadline)", "Set `retriable: true` so it tries again, looking for other arguments that let the refund through", "Return nothing and end the conversation, showing the customer “someone will contact you later”", "Return it as a success with no `isError`, and tell the customer that the refund has gone through"],
  a:[0], e:"For a business error, return that it is not retryable, together with an explanation for the customer." },
{ id:'ccarf-2-07', d:2, o:1, s:3, q:"The search subagent hit a transient timeout. Which behavior is recommended?",
  c:["Try local recovery inside the subagent first; only if that fails, tell the coordinator, with what was tried and any partial results", "Throw the raw error straight up to the coordinator at once, leaving every recovery decision to it while the subagent does nothing", "Swallow the error and return an empty result as a success, letting synthesis go on with the coordinator unaware of the failure", "End the whole workflow as soon as even one subagent returns an error, and finish by showing the user nothing but that error"],
  a:[0], e:"Local recovery first, then propagate with partial results if it cannot be resolved." },
{ id:'ccarf-2-08', d:2, o:1, s:3, q:"Why return “searched, nothing matched” and “could not reach the search service” as different things?",
  c:["The first is a normal result; the second is a failure that calls for a retry or an alternative. Treating them alike leads to bad recovery decisions", "There is no need to tell them apart; handling both in one branch as “no results were obtained” makes for a much simpler implementation overall", "Both should be treated as errors that stop the loop, since letting the model carry on in a state where it has no results at all is dangerous", "Both should be treated as successes; if you tell the model that “nothing was found”, it can decide for itself what the right next action is"],
  a:[0], e:"Tell an access failure apart from a valid empty result." },
{ id:'ccarf-2-09', d:2, o:2, s:3, q:"Giving one agent 18 tools made its tool selection less reliable. Which response is recommended?",
  c:["Cut down to the 4 or 5 the role needs, and remove tools outside its specialty", "Add still more tools, so that every situation it might ever meet is covered", "Keep all 18 and lengthen each description to spell out the differences", "Move to a higher model, so that it picks correctly from among the 18 tools"],
  a:[0], e:"More tools make the decision more complex and less accurate. Scoping by role is the basic rule." },
{ id:'ccarf-2-10', d:2, o:2, s:3, q:"The synthesis agent starts web searches on its own and wastes time. Which design response fits?",
  c:["Take the search tool away from the synthesis agent, give it a narrowly scoped verification tool, and route complex research through the coordinator", "Strengthen the search tool's description, stating “use this only when something is uncertain during synthesis” to limit the occasions it is used", "Allow the synthesis agent every tool, so that it can analyze documents as well as search for itself and the number of round trips comes down", "Delete the synthesis agent, and have the coordinator put the search subagent's output together directly into the final report itself"],
  a:[0], e:"Tools outside an agent's specialty get misused. Give it narrowly scoped tools that match its role." },
{ id:'ccarf-2-11', d:2, o:2, s:6, q:"In an extraction job, the model sometimes answers in conversational text without calling a tool. Which `tool_choice` setting guarantees structured output?",
  c:["`{'type': 'any'}`, making a tool call mandatory (it picks among several schemas)", "`{'type': 'auto'}`, leaving whether to use a tool at all up to the model", "Omit `tool_choice`, and tell it in the system prompt to always use a tool", "Remove the tools, and have it write JSON in the body in a format the prompt gives"],
  a:[0], e:"auto allows a text reply. any forces a call to one of the tools; forcing a specific tool is {\"type\":\"tool\",\"name\":...}." },
{ id:'ccarf-2-12', d:2, o:2, s:6, q:"You want `extract_metadata` always to run before enrichment. Which setting fits?",
  c:["Specify `extract_metadata` in `tool_choice` on the first turn, and handle the later steps in the turns that follow", "Use `tool_choice: 'auto'`, and state in the system prompt “always call extract_metadata first” to convey the order", "Ask in the prompt “please run extract_metadata before moving on to anything else”, and trust the model to keep it", "Put `extract_metadata` first in the tool definitions, relying on the model calling tools from the top of the list"],
  a:[0], e:"Force the specific tool." },
{ id:'ccarf-2-13', d:2, o:2, s:3, q:"A generic `fetch_url` tool lets the agent fetch any URL at all. Which design is safer?",
  c:["Replace it with a constrained tool such as `load_document` that validates document URLs", "Write in the `fetch_url` description: “use only for internal documents, and with care”", "Alongside `fetch_url`, add more tools that return safe URLs for the agent to choose from", "Leave the tool unchanged, and let the model judge which URLs it is allowed to fetch"],
  a:[0], e:"Replace a generic tool with a constrained alternative." },
{ id:'ccarf-2-14', d:2, o:3, s:4, q:"Which pairing is correct for where to put an MCP server the team shares (a Jira integration) and an experimental one you are trying on your own?",
  c:["Shared in the project `.mcp.json` (version controlled); personal in `~/.claude.json`", "Both in `~/.claude.json`, with each person copying the shared part across by hand", "Both in `.mcp.json`, taking care that the personal part does not get committed", "Shared in `~/.claude.json`; the personal one written in the project `.mcp.json`"],
  a:[0], e:"Project scope is shared; user scope is personal." },
{ id:'ccarf-2-15', d:2, o:3, s:4, q:"`.mcp.json` needs a GitHub token, but you do not want to commit a secret to the repository. Which approach is correct?",
  c:["Use environment variable expansion such as `${GITHUB_TOKEN}`, with the value kept in each person's environment", "Write the token directly into `.mcp.json`, and protect it by making the repository a private one", "Put `.mcp.json` in `.gitignore` and give up on sharing it, with each person configuring it by hand", "Run it without a token, and have a person carry out by hand any operation that needs authentication"],
  a:[0], e:"Environment variable expansion keeps the shared configuration without committing the secret." },
{ id:'ccarf-2-16', d:2, o:3, s:4, q:"A capable MCP search tool is available, yet the agent keeps using the built-in `Grep`. Which response fits?",
  c:["Describe in detail in the MCP tool's description what it can do and what it returns, and state when it beats the built-in tool", "Disable `Grep`, forcing every search of the code to go through the MCP tool, whatever kind of search it happens to be", "Add more MCP servers, so that each different kind of search has a dedicated server and a dedicated tool of its own", "Instruct the agent by hand, each and every time you use it, with the words “please use the MCP search tool for this”"],
  a:[0], e:"A thin description leads the agent to prefer the built-in tool." },
{ id:'ccarf-2-17', d:2, o:3, s:4, q:"The agent keeps making exploratory tool calls just to learn “what issues exist”. Which MCP feature improves this?",
  c:["Expose a summary list of the issues as a resource (MCP resources), so they can be surveyed without exploring", "Add more issue search tools, one for each kind of filter, so that the issues become easier for it to find", "Paste the content of every issue into the prompt, so they can be consulted without calling any tool at all", "Forbid exploring the issues altogether, and hand the agent only those issues that a person has picked out"],
  a:[0], e:"Resources provide a catalog of content and cut down exploratory calls." },
{ id:'ccarf-2-18', d:2, o:3, s:4, q:"With several MCP servers configured, which statement about tool availability is correct?",
  c:["Tools from every server are discovered at connection time and are available at once", "Only one server can be used at a time, and switching between them needs a restart", "Servers are switched by hand, with the one in use named in the settings each time", "Tools are enabled one at a time at run time, and then disabled again after use"],
  a:[0], e:"Tools from all configured servers are discovered at connection and usable together." },
{ id:'ccarf-2-19', d:2, o:4, s:4, q:"You want to find every place in the codebase that calls `processPayment`. Which built-in tool do you use first?",
  c:["`Grep` (pattern search over file contents)", "`Glob` (pattern search over file names)", "`Write` (create or overwrite a whole file)", "`Edit` (rewrite one part of a file)"],
  a:[0], e:"Grep searches contents; Glob matches file names." },
{ id:'ccarf-2-20', d:2, o:4, s:4, q:"You want to list the files that match `**/*.test.tsx`. Which tool fits?",
  c:["`Glob`, finding them by file name pattern", "`Grep`, finding them by what the files contain", "`Bash`, running `cat` to look inside them", "`Read`, opening them one by one to check"],
  a:[0], e:"Matching file path patterns is Glob's job." },
{ id:'ccarf-2-21', d:2, o:4, s:4, q:"`Edit` fails with “the text matches in more than one place”. Which fallback is reliable?",
  c:["`Read` the whole file, then rewrite it with `Write`", "Repeat `Edit` once for each of the places", "Run `sed` through `Bash` to replace them all", "Delete the file and recreate it under a new name"],
  a:[0], e:"Edit depends on a unique match. When it fails, switch to Read plus Write." },
{ id:'ccarf-2-22', d:2, o:4, s:4, q:"Which approach is recommended for understanding a large, unfamiliar codebase?",
  c:["Find the entry points with `Grep` and follow the imports with `Read`. Do not read every file up front", "`Read` every file in order, and sort out the flow only once the whole codebase has been taken in", "List the files with `Glob`, and infer the flow from the file names and directory structure alone", "Read only the README and the documentation, and take the flow from those without reading any code"],
  a:[0], e:"Build understanding step by step." },

// ---- Domain 3 ----
{ id:'ccarf-3-01', d:3, o:0, s:2, q:"A new team member's Claude Code does not follow the coding conventions. Existing members have no problem. What is the most likely cause?",
  c:["The conventions sit at user level, not at project level where version control shares them", "The new member uses a different model, which reads and applies the conventions less accurately", "On the new member's network CLAUDE.md fails to load, so the conventions are never applied", "The conventions are so long that loading cuts off partway and the second half is not applied"],
  a:[0], e:"User-level settings apply only to that user." },
{ id:'ccarf-3-02', d:3, o:0, s:2, q:"In a monorepo, each package's CLAUDE.md carries its own duplicate copy of the common standards. Which approach improves maintainability?",
  c:["Reference a common standards file from each package's CLAUDE.md with the `@import` syntax", "Leave the duplication, and fix every package's CLAUDE.md by hand whenever something changes", "Fold every package's content into one giant root CLAUDE.md, and delete the per-package ones", "Delete the common standards, and write only what each package needs in its own CLAUDE.md"],
  a:[0], e:"Modularize with @import." },
{ id:'ccarf-3-03', d:3, o:0, s:2, q:"CLAUDE.md has passed 400 lines and is hard to navigate. Which reorganization is recommended?",
  c:["Split it into topic files under `.claude/rules/`", "Keep adding to the one file, with headings and a contents list", "Cut it by half, deleting the less important conventions", "Move all of it to the user-level CLAUDE.md, emptying the project one"],
  a:[0], e:"Split into rule files by topic." },
{ id:'ccarf-3-04', d:3, o:0, s:2, q:"Behavior is inconsistent from session to session. Which command shows which memory files are being loaded?",
  c:["`/memory`, which opens the memory files for editing", "`/compact`, which compresses and updates the memory", "`/clear`, which wipes the memory to be rewritten", "`/help`, which shows how memory is to be edited"],
  a:[0], e:"/memory lets you check which memory files are loaded." },
{ id:'ccarf-3-05', d:3, o:1, s:2, q:"You want a slash command the whole team can use. Where does it go?",
  c:["The repository's `.claude/commands/` (shared in version control)", "Each person's `~/.claude/commands/` (a personal location)", "Inside `/tmp`, from where it is copied at every start", "In the system prompt, so that it is loaded every time"],
  a:[0], e:"Project scope is shared; user scope is personal." },
{ id:'ccarf-3-06', d:3, o:1, s:2, q:"A codebase analysis skill produces masses of output and clutters the main conversation. Which frontmatter setting fits?",
  c:["`context: fork`, to run it in an isolated subagent context", "An empty `allowed-tools`, so the skill can use no tools at all", "`argument-hint`, to make the skill's arguments explicit", "Turn the skill into a slash command with the same content"],
  a:[0], e:"context: fork keeps verbose output and exploratory context out of the main conversation." },
{ id:'ccarf-3-07', d:3, o:1, s:2, q:"You do not want destructive operations while a skill runs. Which frontmatter do you use?",
  c:["`allowed-tools`, limiting the tools usable while it runs", "`context: fork`, running the skill in a separate context", "`argument-hint`, hinting at the arguments it should get", "`paths`, limiting the files the skill is applied to"],
  a:[0], e:"Restrict tools with allowed-tools." },
{ id:'ccarf-3-08', d:3, o:1, s:2, q:"Developers call a skill with no arguments and it fails. Which frontmatter improves this?",
  c:["`argument-hint`, prompting for the parameters it needs", "`allowed-tools`, limiting the tools that it may use", "`context: fork`, running it in a separate context", "`model`, naming the model that it should run on"],
  a:[0], e:"argument-hint guides the user on arguments." },
{ id:'ccarf-3-09', d:3, o:1, s:2, q:"Which pairing is correct for where “universal standards that always apply” and “procedures called only when needed” belong?",
  c:["Standards in CLAUDE.md (always loaded); procedures in skills (on demand)", "Both standards and procedures in CLAUDE.md, loaded at all times", "Both standards and procedures as skills, loaded only when needed", "Standards in skills (on demand); procedures in CLAUDE.md (always)"],
  a:[0], e:"Always-on standards go in CLAUDE.md; on-demand procedures go in skills." },
{ id:'ccarf-3-10', d:3, o:1, s:2, q:"You want to adapt a team skill to your own taste without affecting colleagues. Which approach fits?",
  c:["Create a personal variant under another name in `~/.claude/skills/`", "Rewrite the shared skill in `.claude/skills/` directly to suit yourself", "Delete the shared skill, and give your own steps by hand in each chat", "Write “override the skill's steps” in CLAUDE.md to change what it does"],
  a:[0], e:"A personal variant goes in user scope under a different name." },
{ id:'ccarf-3-11', d:3, o:2, s:2, q:"You want the infrastructure conventions loaded only when Terraform files are being edited. Which setup fits?",
  c:["In a file under `.claude/rules/`, set `paths` in the frontmatter to the Terraform directory", "Write the Terraform conventions in the project CLAUDE.md, so they are always loaded for all work", "Write the Terraform conventions in a user-level CLAUDE.md, so only the owner's setup applies them", "Only specialists touch the Terraform files, so decide that no conventions need writing anywhere"],
  a:[0], e:"A path-scoped rule loads only when matching files are edited, which cuts irrelevant context and tokens." },
{ id:'ccarf-3-12', d:3, o:2, s:2, q:"Test files are scattered across the codebase. Which way of applying test conventions works better than per-directory CLAUDE.md files?",
  c:["A path-specific rule that uses a glob such as `**/*.test.tsx`", "A CLAUDE.md holding the conventions in every directory with tests", "Everything, test conventions included, in the root CLAUDE.md", "Giving up on telling Claude Code about the test conventions"],
  a:[0], e:"For conventions that span many directories, a rule with a glob pattern is the better tool." },
{ id:'ccarf-3-13', d:3, o:2, s:2, q:"Which is a real advantage of path-specific rules?",
  c:["They load only when relevant files are edited, so there is less irrelevant context and token use", "Every rule is loaded at all times, so the conventions are dependably applied whatever the task is", "The content of the rules is stored encrypted, so highly confidential conventions can be shared safely", "With the rules split up, the model processes them faster and so the response latency gets shorter"],
  a:[0], e:"Conditional loading keeps context focused." },
{ id:'ccarf-3-14', d:3, o:3, s:2, q:"You hand Claude Code a library migration that touches 45 files. Which way of working fits?",
  c:["Investigate and design in plan mode, then implement with direct execution once the plan is settled", "Go ahead with direct execution from the start, and revisit the design as needed while implementing", "Produce the design in plan mode only, and have people read the plan and implement it all by hand", "Open a separate session for each of the files, and implement each one of them by direct execution"],
  a:[0], e:"Large, multi-file tasks with design decisions start in plan mode. Direct execution follows the plan." },
{ id:'ccarf-3-15', d:3, o:3, s:2, q:"A single-file bug fix with a clear stack trace. Which mode fits?",
  c:["Direct execution: just fix it as it stands", "Plan mode: make a plan, and then fix it", "The Explore subagent: explore, then fix", "A new branch: rethink the design, then fix"],
  a:[0], e:"A small change with a clear scope goes to direct execution." },
{ id:'ccarf-3-16', d:3, o:3, s:2, q:"In a multi-phase task, verbose output from the discovery phase fills the main context. Which response fits?",
  c:["Hand discovery to the Explore subagent, and bring only a summary back to main", "Read all of the relevant files in the main session, and take it all in yourself", "Skip the discovery phase, guess what needs to change, and begin implementing", "Recreate the session every time, so that the context is always kept small"],
  a:[0], e:"The Explore subagent is used to isolate verbose exploration." },
{ id:'ccarf-3-17', d:3, o:4, s:2, q:"You describe a data transformation requirement in prose, and Claude's output varies every time. Which improvement is most effective?",
  c:["Show 2 or 3 concrete input and output pairs", "Make the prose explanation longer and fuller", "Move to a higher model for more accuracy", "Lower the temperature to reduce the variation"],
  a:[0], e:"Concrete examples convey a transformation requirement more reliably than prose." },
{ id:'ccarf-3-18', d:3, o:4, s:2, q:"Which way of having Claude Code implement test-first is recommended?",
  c:["Write tests first, covering expected behavior, edge cases and performance needs, then share the failing tests and iterate", "Have the implementation generated first, then once it runs have tests written to match it and confirm that they pass", "Leave tests out, working from generated code and visual checks alone, and fix problems at the point they turn up", "Ask it to “fix it so it works correctly” without showing any test results, so the model has to guess at the cause"],
  a:[0], e:"Sharing test failures and improving step by step is the technique." },
{ id:'ccarf-3-19', d:3, o:4, s:2, q:"In an unfamiliar area (cache design), which pattern do you use before implementing, to avoid missing considerations?",
  c:["The interview pattern: have Claude ask questions that surface points such as invalidation strategy and failure modes, then implement", "Implement at once: assume the requirements were conveyed well enough, get something running first, and fix omissions afterwards", "Tests only: have the cache tests written first and the implementation made to pass them, so the tests cover the considerations", "Ask someone else: consult a colleague who knows caching about the design, then have Claude implement the settled design as is"],
  a:[0], e:"This is the interview pattern." },
{ id:'ccarf-3-20', d:3, o:4, s:2, q:"A review found four problems. Two affect each other; two are independent. How should you put them to Claude?",
  c:["Give the two that interact together in one message, and fix the two independent ones one at a time in turn", "Give all four one at a time in turn, confirming that each has been fixed before moving on to the next", "Give all four at once in one message, have them all fixed together, then check the whole thing again", "Do not name the problems; just ask it to “make this better” and let the model find and fix them itself"],
  a:[0], e:"Interacting problems go together; independent ones go in sequence." },
{ id:'ccarf-3-21', d:3, o:5, s:5, q:"Running Claude Code in CI, the pipeline stalls waiting for input. Which flag is needed?",
  c:["`-p` (`--print`), for non-interactive mode", "`--resume`, to reopen the previous session", "`--verbose`, to print more detailed logs", "`--interactive`, to state interactive mode"],
  a:[0], e:"-p runs non-interactively." },
{ id:'ccarf-3-22', d:3, o:5, s:5, q:"You want review results posted automatically as inline PR comments. Which pair of flags makes the output machine readable?",
  c:["Use `--output-format json` and `--json-schema`", "Use `--verbose` and `--output-format text`", "Use `--resume` together with `--continue`", "Use `--fork` together with `--print`"],
  a:[0], e:"These are the CLI flags for structured output." },
{ id:'ccarf-3-23', d:3, o:5, s:5, q:"Rerunning the review on each new commit posts the same findings again. Which response fits?",
  c:["Include the previous review's findings in context, and tell it to report only new or still unaddressed problems", "Have developers delete the duplicate comments by hand, and carry on with the review mechanism left as it is", "Review only once, the first time a PR is opened, and do not rerun it even when further commits are pushed", "Delete every comment on the PR before each rerun, and post the whole review afresh from a clean slate each time"],
  a:[0], e:"Give the earlier findings as context so only new or open issues are reported." },
{ id:'ccarf-3-24', d:3, o:5, s:5, q:"Test generation proposes scenarios the existing tests already cover. Which improvement fits?",
  c:["Pass the existing test files in as context, so that it avoids duplicates", "Delete all the existing tests before generating, so nothing can overlap", "Stop generating tests, and have developers write the ones needed by hand", "Move to a higher model, so that it infers that the existing tests exist"],
  a:[0], e:"Showing the existing tests prevents duplication." },
{ id:'ccarf-3-25', d:3, o:5, s:5, q:"The tests generated in CI are all of low value. Which improvement is most effective?",
  c:["Write the testing standards, the criteria for a valuable test and the fixtures in CLAUDE.md", "Generate more tests, and have developers pick out and keep the valuable ones among them", "Lower the temperature to steady the output, so tests come out in one consistent form", "Stop generating tests, and go back to developers writing every one of the tests by hand"],
  a:[0], e:"CLAUDE.md supplies the project context when Claude Code runs in CI." },
{ id:'ccarf-3-26', d:3, o:5, s:5, q:"The same session that generated the code is reviewing its own code. What is the problem?",
  c:["It carries over the reasoning from generation and rarely doubts its own decisions. An independent review instance works better", "There is no problem. Because it holds the context of generation, it can give a sharper review that understands the intent", "The session just gets longer and uses up more tokens; the quality of the review itself is not affected in any way", "Within the same session the cache applies and the cost comes down, so if anything the review ought to be done there"],
  a:[0], e:"This is the reason for separating sessions." },

// ---- Domain 4 ----
{ id:'ccarf-4-01', d:4, o:0, s:5, q:"Code review has many false positives. Telling it “be conservative” and “report only high-confidence findings” has not helped. Which response works?",
  c:["Define by explicit category which problems to report (bugs, security) and which to skip (minor style, local conventions)", "Stress in the system prompt “be more conservative and flag only definite problems”, and expect the findings to drop", "Lower the temperature to cut variation, so the same code gets the same findings each time and the noise settles down", "Stop the automated review; now that developers no longer trust it, go back to running on human review alone"],
  a:[0], e:"Vague general instructions do not improve precision. Specific category criteria do." },
{ id:'ccarf-4-02', d:4, o:0, s:5, q:"Which wording improves precision over the instruction “check that comments are accurate”?",
  c:["“Flag a comment only when its claim contradicts what the code does”", "“Check comments against the code with care and flag any problems”", "“Check every comment attached to the code and flag improvements”", "“Report a problem with a comment only when you are highly confident”"],
  a:[0], e:"This is an example of an explicit criterion." },
{ id:'ccarf-4-03', d:4, o:0, s:5, q:"One finding category has a high false positive rate, and developers have started ignoring findings in the accurate categories too. Which short-term response fits?",
  c:["Disable the noisy category for now to win back trust, and improve the prompt in the meantime", "Disable every category and stop the review, restarting once the whole prompt is rebuilt", "Carry on as before, asking developers to bear with it until reading findings becomes a habit", "Tell developers “do not ignore findings even if some are false”, and handle it by process"],
  a:[0], e:"False positives erode trust. Pause at the level of the category." },
{ id:'ccarf-4-04', d:4, o:0, s:5, q:"Severity classification wobbles from run to run. Which approach steadies it?",
  c:["Define explicit criteria for each severity level, with concrete code examples", "Do away with severity levels, and treat every finding in exactly the same way", "Move to a higher model, to raise the accuracy of its severity judgments", "Cut severity down to two levels, “high” and “low”, to simplify the judgment"],
  a:[0], e:"Criteria plus examples give consistent classification." },
{ id:'ccarf-4-05', d:4, o:1, s:1, q:"You want tool selection for ambiguous enquiries to be stable. Which way of building few-shot examples is recommended?",
  c:["Make 2 to 4 examples aimed at ambiguous cases, including why that action was chosen (compared with the other candidates)", "Make 20 examples of simple, typical cases, so that sheer number teaches it a wide range of judgment patterns", "Attach no examples; write the judgment criteria out in detailed prose and have the model apply them as written", "Attach just the one most typical example, and have it reason by analogy from that example for every other case"],
  a:[0], e:"A few examples aimed at the ambiguous situations, with reasons attached." },
{ id:'ccarf-4-06', d:4, o:1, s:5, q:"Even with detailed instructions, the review output format (location, problem, severity, suggested fix) is not consistent. Which step is most effective?",
  c:["Include few-shot examples in the output format you want", "Explain the format instructions in still more detailed prose", "Reshape the output in post-processing to make the format match", "Move to a higher model so it keeps to the format more accurately"],
  a:[0], e:"Few-shot examples are the most effective way to get a consistent format." },
{ id:'ccarf-4-07', d:4, o:1, s:6, q:"Documents vary in form (inline citations versus a reference list at the end, and so on), and required fields come out empty. Which response fits?",
  c:["Add few-shot examples covering a variety of document structures", "Add more required fields, to make clearer what is to be extracted", "Truncate the documents, passing only the parts with a typical structure", "Have people extract from the odd documents, outside the automation"],
  a:[0], e:"Few-shot examples also help with varied document structures." },
{ id:'ccarf-4-08', d:4, o:1, s:5, q:"Few-shot examples work only on “the cases listed in advance” and do not generalize to new patterns. What is a likely cause?",
  c:["The examples show surface patterns without the reasoning behind the decision. Make examples that convey the criteria", "There are too many examples and the model is pulled toward their details. Cut the number of examples down to two", "There are too few examples for it to learn the pattern. Raise the number to 50 so that every case is covered", "Few-shot works only on inputs identical to the examples, so generalizing from them is impossible in principle"],
  a:[0], e:"Examples with reasons help generalization." },
{ id:'ccarf-4-09', d:4, o:2, s:6, q:"You ask for JSON in prose, and syntax errors creep in. Which measure is most dependable?",
  c:["Define a tool with a JSON schema, and take the structured data from the `tool_use` block", "Stress in the prompt: “return strict JSON only, with no prose before or after it”", "Cut the JSON-looking part out of the output with a regular expression, and repair it if broken", "Drop JSON and have it return CSV, reading the rows and columns on the application side"],
  a:[0], e:"Schema conformance through tool_use is the most reliable." },
{ id:'ccarf-4-10', d:4, o:2, s:6, q:"Tool use removed the JSON syntax errors, but outputs where “the line items do not add up to the total field” remain. Why?",
  c:["A strict schema removes syntax errors, but cannot prevent semantic errors (sums that do not match, swapped fields)", "The schema is badly written and its field descriptions are too thin, so the correct values do not get filled in", "It is a bug in the tool use mechanism; values can come out broken even when the output matches the schema", "The model does not understand JSON structure; the form is right, but it has not grasped what the values mean"],
  a:[0], e:"Syntax and meaning are separate problems." },
{ id:'ccarf-4-11', d:4, o:2, s:6, q:"When the source document lacks a piece of information, the model makes up a plausible value to fill the required field. What is the schema design response?",
  c:["Make fields whose information may be absent optional (nullable)", "Keep it required and ask in the prompt “use an empty string if unknown”", "Delete that field from the schema, removing it from the extraction", "Move to a higher model, so that it does not fabricate what is missing"],
  a:[0], e:"Required fields invite fabrication. Make them nullable." },
{ id:'ccarf-4-12', d:4, o:2, s:6, q:"Values not listed in the category enum keep turning up. Which design keeps it extensible?",
  c:["Add `'other'` to the enum with a detail string field, and provide `'unclear'` as well for ambiguous cases", "Drop the enum for free text, so the model can return a fitting name for any kind of document at all", "Discard documents that match no enum value, and extract only from the kinds of document already known", "Grow the enum to 100 values, covering every kind of document you can imagine ahead of time, with no gaps"],
  a:[0], e:"The pattern is \"other\" plus detail, and \"unclear\"." },
{ id:'ccarf-4-13', d:4, o:2, s:6, q:"The document type is unknown, and there are several extraction schemas (one for invoices, one for contracts). Which `tool_choice` fits?",
  c:["`'any'`, which guarantees a call to one of the tools while the model picks the schema", "Force one specific tool, extracting with that same schema whatever kind of document it is", "`'auto'`, leaving it to the model's judgment, including whether to use a tool at all", "Merge the tools into one, with the fields for every kind of document in a single schema"],
  a:[0], e:"Several schemas and an unknown type call for any." },
{ id:'ccarf-4-14', d:4, o:3, s:6, q:"An extraction result failed validation. Which retry design is appropriate?",
  c:["Ask again with the original document, the failed extraction and the specific validation errors, so it self-corrects", "Resend the very same prompt as it is, and wait for sampling variation to produce a correct result eventually", "Ignore the validation failure and take the last extraction result, passing it downstream just as it is", "Send everything that fails validation to a person, and never have the model retry an extraction at all"],
  a:[0], e:"Retry with the error attached." },
{ id:'ccarf-4-15', d:4, o:3, s:6, q:"After three retries the “contract renewal date” still cannot be extracted. The document does not contain it; it is in a separate appendix. Which decision is correct?",
  c:["The information is not in the document, so retrying is futile. Provide the appendix or send it to a person", "Raise the number of retries to 10, and keep on repeating until the correct value finally comes out", "Move to a higher model and retry, so that it manages to read the value out of the document", "When the value is not in the document, have the model guess, and return that as an estimate"],
  a:[0], e:"Retrying is useless when the information is absent. It helps when the problem is one of format." },
{ id:'ccarf-4-16', d:4, o:3, s:5, q:"You want to analyze systematically which findings developers dismiss. Which field should be added to the output?",
  c:["The code construct that triggered the finding (`detected_pattern`)", "The length of the finding text, with paragraph and sentence counts", "The time the review ran, and the total time that it took to process", "The name and version of the review model, plus its settings"],
  a:[0], e:"detected_pattern lets you analyze false positive patterns." },
{ id:'ccarf-4-17', d:4, o:3, s:6, q:"You want to detect automatically the invoices whose total does not match the line items. Which self-correcting design fits?",
  c:["Extract both the stated total and a calculated total, and flag any mismatch with a boolean", "Extract the total only and not the line items, so that a mismatch can never arise at all", "Ignore mismatches as reading error by the model, and take the total written in the document", "Have people check every extraction against the source, leaving mismatches to the human eye"],
  a:[0], e:"Extracting both values makes the inconsistency visible." },
{ id:'ccarf-4-18', d:4, o:4, s:5, q:"Of “pre-merge checks on a PR” and “a weekly code quality audit”, which suits the Message Batches API?",
  c:["Batch for the weekly audit; synchronous for the pre-merge checks", "Process both through the Batch API, to keep the cost at its lowest", "Process both through the synchronous API, for the fastest results", "Batch for the pre-merge checks; synchronous for the weekly audit"],
  a:[0], e:"Batch suits non-blocking work that can tolerate latency." },
{ id:'ccarf-4-19', d:4, o:4, s:6, q:"Which is a real constraint of the Batch API?",
  c:["A multi-turn exchange that runs a tool and returns its result within one request is not possible", "Streaming is mandatory in a batch, so the results have to be received incrementally as they come", "A batch accepts only one item at a time, so requests cannot be submitted together in one go", "Batch processing is guaranteed to take 24 hours or more, so it cannot be used for anything urgent"],
  a:[0], e:"Batch does not support multi-turn tool calling. 50% discount, up to 24 hours, matched up by custom_id." },
{ id:'ccarf-4-20', d:4, o:4, s:6, q:"In a batch, some documents failed for exceeding the context limit. Which handling is appropriate?",
  c:["Identify the failures by `custom_id`, fix them, and resubmit only those", "Resubmit the whole batch as is, processing the successes over again too", "Ignore the failures, and pass only the successful results downstream", "Drop batch and move every item to the synchronous API, one at a time"],
  a:[0], e:"Resubmit only what failed." },
{ id:'ccarf-4-21', d:4, o:4, s:6, q:"What should you do before batch processing 10,000 items for the first time?",
  c:["Refine the prompt synchronously on a sample to raise first-pass success, then submit at volume", "Submit every item to batch straight away, then fix the prompt from the results and resubmit", "Process every item through the synchronous API with no batch, checking results one by one", "Submit every item to batch on a higher model, and do not adjust the prompt in any way"],
  a:[0], e:"Tuning on a sample first lowers the cost of resubmission." },
{ id:'ccarf-4-22', d:4, o:4, s:6, q:"There is an SLA to return results within 30 hours. If batch processing can take up to 24 hours, which submission design fits?",
  c:["Submit batches in short windows, such as every 4 hours, so the worst case stays inside the SLA", "Submit everything together once a day, to make the fullest possible use of the batch discount", "Change the SLA itself to 48 hours, so that it lines up with how long batch processing takes", "Switch over to the synchronous API, processing in a way that is certain to keep the SLA"],
  a:[0], e:"Work back from the SLA to the submission frequency." },
{ id:'ccarf-4-23', d:4, o:5, s:5, q:"You want more accurate review of generated code. Which design is most effective?",
  c:["Have a separate instance review it, one without the reasoning context of generation", "Tell the same session to “self-review the code that you have just generated”", "Raise the extended thinking budget, so it thinks more deeply while generating", "Run the generation again from the start, and take the second result"],
  a:[0], e:"An independent instance is more effective than self-review or extended thinking." },
{ id:'ccarf-4-24', d:4, o:5, s:5, q:"You want finer routing of review findings. What is worth adding to the verification pass?",
  c:["Have it attach a confidence to each finding, calibrate it, and use it for routing", "Treat every finding alike, with no distinction made by severity or by confidence", "Attach no confidence; the reviewer judges from how the finding is worded", "Limit the number of findings per run, reporting only the top few of them"],
  a:[0], e:"Confidence is calibrated against labeled data before it is used for routing." },

// ---- Domain 5 ----
{ id:'ccarf-5-01', d:5, o:0, s:1, q:"Summarizing a long support conversation as it went, the refund amount and order number blurred into things like “a small refund”, and the case was mishandled. Which response fits?",
  c:["Keep transaction facts as “case facts”, separate from the summary, and include them in every prompt", "Raise the length limit on the summary, so transaction facts are less likely to drop out of it", "Stop summarizing and send the full conversation history, so that no transaction fact is lost", "Leave transaction figures out of the summary, and fetch them again by tool when they are needed"],
  a:[0], e:"Progressive summarization tends to lose numbers. Keep a separate layer of structured facts." },
{ id:'ccarf-5-02', d:5, o:0, s:1, q:"`lookup_order` returns more than 40 fields, but a return needs only 5 of them. Which context response fits?",
  c:["Trim it to only the fields needed before it goes into history", "Keep every field as is, and let the model find the parts it needs", "Skip the tool, and ask the user to type in the information needed", "Move to a model with a bigger context, so the full result still fits"],
  a:[0], e:"Tool results consume tokens out of proportion to their relevance. Trim them." },
{ id:'ccarf-5-03', d:5, o:0, s:3, q:"Findings in the middle of a long input drop out of the report. Which response to “lost in the middle” fits?",
  c:["Put a summary of the key findings at the start, and organize the detail under explicit headings", "Put all of the information at the end, gathering what matters in the part the model reads last", "Make the input longer still, repeating the important information several times so it sticks", "Leave the order of the information as it is, and tell the model “read the middle carefully too”"],
  a:[0], e:"This counters the position effect." },
{ id:'ccarf-5-04', d:5, o:0, s:3, q:"The downstream synthesis agent has a small context budget. Which change to the upstream agents fits?",
  c:["Return structured data such as key points, quotes and relevance scores, not verbose prose", "Pass on all of the upstream output as is, and let the synthesis agent pick what it needs", "Remove the synthesis agent, and have the coordinator combine the upstream output directly", "Drop the upstream subagents, and have the synthesis agent do the search and analysis itself"],
  a:[0], e:"Structured, compact upstream output protects the downstream budget." },
{ id:'ccarf-5-05', d:5, o:1, s:1, q:"The customer says at the outset: “I want to talk to a person.” What is the agent's correct behavior?",
  c:["Escalate to a person at once, without attempting to investigate", "Try to resolve it first, and then judge whether it is needed", "Escalate if sentiment analysis shows a high level of anger", "Try to resolve it three times, and hand over only if that fails"],
  a:[0], e:"An explicit request for a human is honored immediately." },
{ id:'ccarf-5-06', d:5, o:1, s:1, q:"The customer is irritated, but the problem is a simple one the agent can solve. Which response fits?",
  c:["Acknowledge the irritation and offer the fix; escalate if the customer asks again for a person", "Escalate to a person at once, handing over without the agent attempting any resolution", "Ignore the emotional language, and process only the content of the enquiry in a flat manner", "Do not continue talking with an irritated customer; end the chat and offer a later contact"],
  a:[0], e:"Sentiment is an unreliable proxy for escalation. If it can be resolved, offer the resolution." },
{ id:'ccarf-5-07', d:5, o:1, s:1, q:"The customer demands “match the price on a competitor's site”. Policy covers only price adjustments within your own site. Which decision is correct?",
  c:["Policy is silent here (there is a gap), so escalate", "It is not written in the policy, so refuse the request", "Decide independently and discount what seems fair", "Treat it as out of scope, and ignore it without replying"],
  a:[0], e:"Ambiguity or a gap in policy is a condition for escalation." },
{ id:'ccarf-5-08', d:5, o:1, s:1, q:"`get_customer` returned three customers with the same name. What is the agent's correct behavior?",
  c:["Ask the customer for another identifier (email, phone, order number)", "Pick the one of the three with the most recent order, and proceed", "Pick the first of the three in the search results, and proceed", "Refund all three of them, and cancel the wrong ones afterwards"],
  a:[0], e:"With multiple matches, do not pick by heuristic. Ask for confirmation." },
{ id:'ccarf-5-09', d:5, o:1, s:1, q:"Which prompt design does most to steady escalation decisions?",
  c:["Include explicit escalation criteria, with few-shot examples of cases to escalate and cases to resolve autonomously", "Write in the system prompt “judge each situation appropriately and escalate as needed”, leaving it to the model", "Have the model report its own confidence and escalate when that is low, without writing down any criteria", "To remove any variation in the decision, always escalate every single enquiry to a person, whatever it is about"],
  a:[0], e:"Explicit criteria plus examples. Self-reported confidence is not a reliable proxy for complexity." },
{ id:'ccarf-5-10', d:5, o:2, s:3, q:"The search subagent returns only “search unavailable” to the coordinator. Which improvement fits?",
  c:["Return a structured error with the failure type, the queries tried, partial results and alternatives", "Return no error; pass back an empty result as a success so that the synthesis can carry on", "Stop the whole workflow on a single failed search, and show the user the error that occurred", "Report only the fact of the failure in a single line, and keep the detail in the server logs alone"],
  a:[0], e:"Structured error context is what lets the coordinator decide how to recover." },
{ id:'ccarf-5-11', d:5, o:2, s:3, q:"Choose two things regarded as anti-patterns in multi-agent error handling.",
  c:["Swallowing an error and returning an empty result as a success", "Ending the entire workflow because of one single failure", "Trying local recovery first, and propagating upward if it fails", "Telling the coordinator of a failure with partial results attached"],
  a:[0,1], e:"Silent suppression and all-or-nothing termination are both anti-patterns." },
{ id:'ccarf-5-12', d:5, o:2, s:3, q:"The final report goes out while some sources could not be retrieved. Which form of synthesis output fits?",
  c:["Use coverage annotations to show which findings are well supported and which areas have gaps", "Issue it as a finished piece without mentioning the gaps, leaving readers to notice what is missing", "Do not issue a report while sources are missing; rebuild it later once those sources are back", "Fill the missing parts with guesses from the model's knowledge, so it has the shape of a full report"],
  a:[0], e:"Use coverage annotations." },
{ id:'ccarf-5-13', d:5, o:3, s:4, q:"In a long exploration session, Claude has started describing “typical patterns” in place of the specific classes it found at the beginning. Choose two appropriate responses.",
  c:["Have it record key findings in a scratchpad file, and refer to that for later questions", "Compress the context with `/compact`, keeping the key points and going on in the same chat", "Carry on as before, pointing out each loss of accuracy on the spot and having it corrected", "Move to a model with a bigger context, and carry on to the end in that same conversation"],
  a:[0,1], e:"Responses to context degradation: a scratchpad, /compact, and delegating to subagents." },
{ id:'ccarf-5-14', d:5, o:3, s:4, q:"You want specific questions investigated, such as “find every test file” and “trace the dependencies of the refund flow”, while keeping the main agent's understanding intact. Which design fits?",
  c:["Launch a subagent for each question, with main handling the high-level coordination", "The main agent investigates every question itself and writes up the results itself", "Narrow the questions to the single most important one, and leave the rest for later", "People investigate the codebase, and the agent is used only to summarize what they find"],
  a:[0], e:"Subagents isolate verbose exploration." },
{ id:'ccarf-5-15', d:5, o:3, s:4, q:"A job in which several agents run for hours has crashed. Which design can recover?",
  c:["Each agent exports its state, and on resume the coordinator reads a manifest and injects that state back in", "After a crash start again from the beginning, saving no intermediate state and rerunning every agent from zero", "Design on the assumption that it never crashes; if it does, a person reads the logs and continues by hand", "Only log each agent's output; on resume a person reads the logs and passes them to the coordinator by hand"],
  a:[0], e:"Recovery comes from persisting structured state and loading it through a manifest." },
{ id:'ccarf-5-16', d:5, o:3, s:4, q:"After exploration phase 1, you launch the phase 2 subagents. Which procedure is recommended?",
  c:["Summarize the key findings of phase 1, and inject them into the initial context of the phase 2 subagents", "Pass the whole of the phase 1 output to the phase 2 subagents as is, and let them pick out what they need", "Pass on nothing at all from phase 1, and have the phase 2 subagents investigate from the very beginning", "Skip phase 2 altogether, and write the final report from nothing more than the results of phase 1"],
  a:[0], e:"Carry findings across phases as a summary." },
{ id:'ccarf-5-17', d:5, o:4, s:6, q:"Overall accuracy of the extraction system is 97%, so it was decided to take human review off the high-confidence results. Which risk is being overlooked?",
  c:["Aggregate accuracy may hide weak performance on some document types or fields. Validate by type and by field", "97% is a high enough accuracy that there is hardly any risk; automate as is and drop the human review entirely", "It is short of 100% only because the model is old; a newer model will raise accuracy enough to automate", "Automation is dangerous whatever the accuracy, so add reviewers and set up to check every single item by hand"],
  a:[0], e:"This is the trap of an aggregate metric." },
{ id:'ccarf-5-18', d:5, o:4, s:6, q:"After auto-approving high-confidence extractions, you still want to measure the error rate continually and catch new error patterns. Which method fits?",
  c:["Inspect high-confidence extractions regularly by stratified random sampling", "Do not inspect what was auto-approved; people look at the low-confidence ones only", "Stop the auto-approval, and have people look at and confirm every extraction", "Look into items only when a customer or a downstream team complains about them"],
  a:[0], e:"Measure continually with stratified sampling." },
{ id:'ccarf-5-19', d:5, o:4, s:6, q:"To make the best use of limited reviewer time, which extractions should go to people?",
  c:["Those where model confidence is low, or the source document is ambiguous or contradictory", "Those picked at random from the whole set, with no regard to their content or confidence", "A fixed number taken from the front in processing order, with no regard to confidence", "Those where model confidence is high, which can then be used as evidence of accuracy"],
  a:[0], e:"Prioritize low confidence and ambiguous sources." },
{ id:'ccarf-5-20', d:5, o:4, s:6, q:"You want to set review thresholds from field-level confidence. Which procedure is correct?",
  c:["Have field-level confidence output, calibrate it on a validation set, then set the thresholds", "Use the model's self-reported confidence as it is, routing on a threshold fixed at 0.9", "Do not use confidence, as it cannot be trusted; send every item to human review alike", "Set the thresholds by the operators' instinct, adjusting them little by little if problems arise"],
  a:[0], e:"Confidence needs calibrating." },
{ id:'ccarf-5-21', d:5, o:5, s:3, q:"Claims in the final report have stopped carrying their sources. What is a likely cause?",
  c:["Summarizing lost the link between claim and source. Have a structured mapping output and preserve it downstream", "Readers do not need sources, so it does not matter if they drop out when summarizing; just check the body text", "A model fault is dropping the sources. Moving to a higher model will make them survive in the summaries", "There are too many sources to fit in a summary. Cut the number down, and keep only the main two or three"],
  a:[0], e:"Claim-to-source mapping has to be kept as structure through every stage." },
{ id:'ccarf-5-22', d:5, o:5, s:3, q:"Two credible sources give different statistics. Which handling is appropriate?",
  c:["Do not pick arbitrarily; include both with the conflict annotated and attributed, and let the coordinator reconcile", "Adopt the larger of the two figures, and discard the smaller one as an error without including it in the report", "Adopt whichever of the two sources looks the more recent, and discard the older one without including it", "Conflicting information cannot be trusted, so delete both of the figures and include neither in the report"],
  a:[0], e:"Keep a conflict, with an annotation." },
{ id:'ccarf-5-23', d:5, o:5, s:3, q:"Data from 2019 and from 2024 gets reported as a “contradiction”. Which design prevents this?",
  c:["Require the publication date and data collection date in each subagent's structured output", "Throw away all data older than a set point, and use only the newer data in the synthesis", "Ignore contradictions that come from timing, and adopt whichever value was found first", "Do not structure the dates; just write them as prose somewhere within the body text"],
  a:[0], e:"Structure the dates so that a difference in time is not mistaken for a contradiction." },
{ id:'ccarf-5-24', d:5, o:5, s:3, q:"Which format is recommended for a synthesis report?",
  c:["Separate established findings from contested ones by section, and render each as a table, prose or a list to suit it", "Put every finding in the same bulleted format, unified so that readers can go through them all in a single list", "Leave out contested findings as they would confuse readers, and write up only the established ones as prose", "Write everything as prose, explaining figures and findings in the flow of the text with no tables or lists"],
  a:[0], e:"Distinguish what is established from what is contested, and fit the format to the content." },
// ---- Added from study notes ----
{ id:'ccarf-1-25', d:1, o:0, q:"Which way of deciding that an agentic loop has ended does NOT belong to the patterns to avoid?",
  c:["Ending when the response's `stop_reason` becomes `end_turn`", "Ending when the response text contains the sentence “I have finished”", "Making “the iteration count reached 10” the main stop mechanism", "Taking any returned assistant text block as the signal of completion"],
  a:[0], e:"Three patterns to avoid: parsing the wording (it depends on phrasing), an iteration cap as the main stop mechanism (a cap is a safety device), and treating returned text as completion (text can arrive together with a tool request)." },
{ id:'ccarf-1-26', d:1, o:1, q:"The coordinator of a research system always runs every request through web search → document analysis → synthesis → report generation. Which improvement matches the recommended design?",
  c:["Analyze what the request needs and pick only the necessary subagents dynamically. A simple request need not go through every stage", "Running every stage is right, as skipping any lowers quality. Hold cost down by moving each subagent to a lower model instead", "Connect the subagents to one another directly, passing results along without the coordinator. Fewer round trips make it faster", "Keep the order of stages fixed, double the number of subagents so each stage runs twice, and choose results by majority vote"],
  a:[0], e:"Hub and spoke (subagents do not talk to each other directly), plus dynamic selection by the complexity of the request. Divide work by topic or source type; cutting it too fine leaves gaps." },
{ id:'ccarf-1-27', d:1, o:2, q:"In the Agent SDK you want the coordinator to launch subagents. Which combination of mechanisms is correct?",
  c:["Launch with the Task tool, with `\"Task\"` in the coordinator's `allowedTools`. Per-type settings go in `AgentDefinition`", "Launch with `tool_choice: \"any\"`, listing subagent types and roles in the `system` prompt for it to choose among", "Launch from a hook (PreToolUse), switching the subagent type per matching file through paths in `.claude/rules/`", "Launch with `fork_session`, telling subagent types apart by a prefix on the session name passed to `--resume`"],
  a:[0], e:"A subagent does not inherit the parent's context automatically, and shares no memory between invocations. Pass the context it needs explicitly in the request." },
{ id:'ccarf-1-28', d:1, o:2, q:"The coordinator wants to run three search subagents in parallel. Which way is recommended?",
  c:["Emit several Task calls within a single response from the coordinator", "Launch one per turn, waiting for each result before launching the next one", "Put the three search topics in one Task call, for one subagent to do in turn", "Set up three coordinators, each of which launches a single subagent"],
  a:[0], e:"Parallel launch is several Task calls in one response. The request states the research goal and quality criteria, not step-by-step instructions." },
{ id:'ccarf-1-29', d:1, o:3, q:"Identity must always be verified before a refund is processed. Which means makes the order hold deterministically?",
  c:["A prerequisite gate: block calls to `process_refund` until `get_customer` has returned a verified customer ID", "Write “always verify identity before a refund” in bold in the system prompt, and attach few-shot examples too", "Write “use only after identity verification” in the `process_refund` description, with `tool_choice` set to `auto`", "After the refund, a PostToolUse hook logs whether identity was verified; if not, a person reverses it next day"],
  a:[0], e:"A prompt instruction only raises the odds of compliance; the failure rate never reaches zero. An order that must hold is enforced in code, with hooks and prerequisite gates." },
{ id:'ccarf-1-30', d:1, o:3, q:"When escalating to a person partway through, which set of items belongs in the handoff summary?",
  c:["Customer details (customer ID), root cause analysis, amounts (such as the refund), and the recommended action", "The full conversation text, the list of tools used, token counts per turn, and the model's confidence", "A rating of the customer's mood, an apology to the agent, a discount for next time, and lessons learned", "The customer's name and address, the last 4 digits of the payment card, and the full purchase history"],
  a:[0], e:"Assume the person taking over cannot see the transcript, and put together a structured summary." },
{ id:'ccarf-1-31', d:1, o:4, q:"Date formats returned by several MCP tools differ (Unix timestamps, ISO 8601), and the model mixes them up. Which Agent SDK mechanism addresses this?",
  c:["A PostToolUse hook intercepts tool results and unifies the format before the model processes them", "Write in the system prompt: “date formats may differ from tool to tool, so take care with them”", "Contact the author of each MCP server, and get every server's date format changed to ISO 8601", "Pass tool results through a subagent to reformat them, and return its output to the coordinator"],
  a:[0], e:"Intercepting tool results (PostToolUse) is for normalizing data. Intercepting outgoing tool calls is for enforcing compliance rules, such as blocking a refund over $500 and routing it to a person." },
{ id:'ccarf-1-32', d:1, o:6, q:"Last week's session analyzed the codebase, but the code has changed substantially since. Which decision is sound?",
  c:["Start a new session seeded with a structured summary. It is more reliable than resuming with stale tool results", "Resume with `--resume`. Having the earlier context is always better, and the model detects changes for itself", "Branch with `fork_session`. The new code can be analyzed without contaminating the original session at all", "Neither resume nor start fresh as is: paste the whole earlier analysis into CLAUDE.md, then open a new session"],
  a:[0], e:"Resume if the earlier context is still largely valid; if the tool results are stale, start fresh with a summary. If only some files changed, say exactly which and have just those parts re-analyzed." },
{ id:'ccarf-2-23', d:2, o:0, q:"The tool descriptions are well written, yet an unintended tool keeps being chosen. What should be reviewed?",
  c:["The system prompt. An instruction that reacts to certain keywords may be creating an unintended tie to a tool", "The number of tools. Even with good descriptions, selection is unstable with 3 or more, so cut down to 2", "The model tier. Telling descriptions apart takes a higher model, so the right step is to switch to Opus", "`temperature`. Tool selection is probabilistic, so setting it to 0 makes it choose as the descriptions say"],
  a:[0], e:"Three common problems: two tools with nearly the same description → rewrite names and descriptions. A generic tool with many roles → split by purpose. Good descriptions but wrong picks → review the system prompt." },
{ id:'ccarf-2-24', d:2, o:1, q:"Which pair of MCP tool error categories is “pointless to retry with the same request”?",
  c:["Business rule (a policy violation) and permission (no access rights)", "Transient (a timeout) and validation (the input was invalid)", "Transient (a brief service outage) and permission (no access rights)", "Validation (the input was invalid) and business rule (a policy violation)"],
  a:[0], e:"Transient errors are worth retrying. Validation errors work once the input is fixed. Business rule and permission errors cannot succeed with the same request. Returning errorCategory and isRetryable as structure prevents wasted retries." },
{ id:'ccarf-2-25', d:2, o:2, q:"The synthesis subagent was given `fetch_url`, which can fetch any URL, and began doing web searches on its own. Which response is a “constrained alternative”?",
  c:["Replace `fetch_url` with `load_document`, which validates a document URL before reading it", "Add the sentence “not to be used for searching” to `fetch_url`, and go on giving it to synthesis", "Formally give synthesis a web search tool too, so it owns search and the coordinator does less", "Remove all of the synthesis agent's tools, with the coordinator fetching documents as strings"],
  a:[0], e:"Three levers: restriction by role, constrained alternatives, and limited cross-role tools (something like verify_fact for a frequent need, with complex cases going through the coordinator)." },
{ id:'ccarf-2-26', d:2, o:3, q:"The agent does not use a capable MCP tool and keeps choosing the built-in Grep. What is the cause?",
  c:["The MCP tool's description is thin and does not convey its capabilities and output. Write it out in detail", "MCP tools are not discovered at connection time, and go unused unless each is explicitly enabled", "Built-in tools always take priority over MCP tools by specification, and that cannot be changed", "It was written in `~/.claude.json` and not in `.mcp.json`, so it is disabled within the project"],
  a:[0], e:"Tools from every configured MCP server are discovered at connection and usable together. Whether one gets chosen depends on its description." },
{ id:'ccarf-2-27', d:2, o:3, q:"Which correctly sorts the three MCP primitives by “who controls it”?",
  c:["Tools by the model (Claude decides when to call), resources by the app (app code fetches the data), prompts by the user (started from a button or slash command)", "Tools by the user (started from a slash command), resources by the model (Claude picks the data it needs), prompts by the app (app code inserts them)", "Tools, resources and prompts are all called by the model as it needs them. The app and the user just receive results and take no part in control", "Tools by the app (app code executes them), resources by the user (picked from a menu), prompts by the model (Claude generates the wording itself)"],
  a:[0], e:"Resources are read by URI; there are direct resources with a fixed URI and templated resources with parameters. Prompts are polished templates from the server author, usable from any client." },
{ id:'ccarf-2-28', d:2, o:4, q:"Replacing a string with the Edit tool failed. Which cause and response fit?",
  c:["The target string is not unique in the file. Read the whole file, then write it back with Write", "The file is too large. Pull out just the matching lines with Grep, and then run Edit on those", "The permission mode is plan. Switch over to acceptEdits and then run the same edit again", "Edit works on new files only. Rewrite an existing file with sed run through the Bash tool"],
  a:[0], e:"Edit makes a targeted change by matching a unique string. To understand a codebase, find the entry points with Grep and follow imports with Read, building up in steps. Do not read every file first." },
{ id:'ccarf-3-27', d:3, o:0, q:"One instruction fails to take effect only for a member who has just joined the team. What should you suspect first?",
  c:["The instruction is written in someone's user-level settings (`~/.claude/CLAUDE.md`), not at project level", "That member's version of Claude Code is old, and does not support the syntax used in CLAUDE.md", "The instruction sits in `.claude/rules/`, and no file that matches its paths has been opened", "That member starts up in plan mode, and so CLAUDE.md is not being loaded for them at all"],
  a:[0], e:"A user-level CLAUDE.md applies to that person only and is not shared through version control. /memory shows which memory files are loaded." },
{ id:'ccarf-3-28', d:3, o:0, q:"CLAUDE.md had grown long, so it was split into several files with `@import`. Which statement is correct?",
  c:["Imports are expanded in place at startup, so the amount of context loaded does not shrink. It is a way to organize; path-scoped rules are what cut the amount", "Imported files are read only at the moment they are needed, so the amount of context loaded at startup goes down by a great deal once the file is split", "Imported files take a higher priority than CLAUDE.md itself, so whenever the two contradict one another the imported side is the one that wins out", "Imports can be followed only one level deep, so the files that were split out must never contain any further imports of their own inside them"],
  a:[0], e:"CLAUDE.md is guidance, not enforced configuration, and every line competes for attention. What really reduces context is paths in .claude/rules/, which load only when a matching file is edited." },
{ id:'ccarf-3-29', d:3, o:1, q:"You want to use a skill the team shares with slightly different steps, for yourself only. What is recommended?",
  c:["Create your own skill under a different name in `~/.claude/skills/`, leaving colleagues unaffected", "Rewrite the SKILL.md in the team's `.claude/skills/` directly, and commit the change to the repo", "Create one in `~/.claude/skills/` with the team skill's name, overriding it on your machine only", "Skills can only ever be shared, so your own personal steps have to be written in CLAUDE.md"],
  a:[0], e:"Project skills live in .claude/skills/, personal ones in ~/.claude/skills/. A skill is a task-specific procedure called when needed; CLAUDE.md holds common conventions that are always loaded." },
{ id:'ccarf-3-30', d:3, o:1, q:"Which is the skill most worth creating first?",
  c:["One that verifies Claude's own work: it runs the tests, reads the diff, and reports pass or fail with evidence", "One that writes commit messages: it is used most often, the gain shows at once, and team style falls into line", "One that summarizes the whole codebase: call it at the start of each session to build context and save exploring", "One that rewrites CLAUDE.md automatically: add a rule for each mistake, mechanically preventing bloat and conflict"],
  a:[0], e:"Do not let verification depend on a person remembering to ask for it. “Done” means the gate was run and its result was checked and stated. Once you have typed the same multi-step instruction twice, make it a skill." },
{ id:'ccarf-3-31', d:3, o:2, q:"Test files are scattered through the whole codebase. Where is the recommended place for conventions that apply only to test files?",
  c:["A file in `.claude/rules/` with `paths: [\"**/*.test.tsx\"]`. It takes effect by file type, wherever the file sits", "A CLAUDE.md in each directory holding the same copy of the test conventions. Nearer files win, so it works reliably", "The root CLAUDE.md, with “follow these conventions when editing test files”. It is always read, so Claude judges", "A testing skill, called by hand each time a test file is opened. It is read only when needed, keeping context clean"],
  a:[0], e:"When conventions span several directories, use a path-scoped rule. It loads only when a matching file is edited, which cuts irrelevant context and token use." },
{ id:'ccarf-3-32', d:3, o:4, q:"For a cache layer design, you want to draw out before implementation the considerations the developer had not thought of (invalidation policy, how failures occur). Which technique fits?",
  c:["The interview pattern: have Claude ask questions before implementing", "Test-driven iteration: write performance tests first, share the failures", "Concrete input/output examples: show the transformation in 2 or 3 pairs", "Specific test cases: fix boundary conditions like nulls with input examples"],
  a:[0], e:"Of the four techniques, the interview pattern is the one for design in an unfamiliar area. For feedback, put interacting problems together in one detailed message, and fix independent ones in turn." },
{ id:'ccarf-3-33', d:3, o:5, q:"Code review runs in CI, and the same findings are posted again with every commit. Which response follows good practice?",
  c:["On a re-review, include the previous findings in context and have it report only new and unaddressed problems", "Narrow the review down to the diff of the latest commit alone, and show it none of the changes made before that", "Remove duplicates by string comparison before posting, discarding any finding whose wording has appeared before", "Cut the review back to once a week, and do not run it each time that a commit is pushed to the pull request"],
  a:[0], e:"In the same way, in test generation put the existing test files in context to prevent duplicate suggestions, and write the testing standards and the conditions for a valuable test in CLAUDE.md." },
{ id:'ccarf-4-25', d:4, o:0, q:"You want fewer false positives in code review. Which instruction does NOT improve precision?",
  c:["A general instruction such as “be conservative” or “report only high-confidence findings”", "A specific criterion: “flag a comment only when the behavior it states contradicts the code”", "A definition: “report bugs and security; do not report minor style or local conventions”", "An instruction giving classification criteria with a concrete code example per severity"],
  a:[0], e:"Do not rely on filtering by confidence; define what is reported and what is not. Disable a category with many false positives for a while, restoring developer trust while the prompt is fixed." },
{ id:'ccarf-4-26', d:4, o:1, q:"In extraction, required fields often come back empty or null. Which few-shot response addresses this?",
  c:["Add examples of correct extraction from documents in differing formats", "Raise the number of examples above 10, to cover every document format", "Cut the examples and keep instructions only, trusting it to generalize", "Add examples that fill an empty field with the fixed value “unknown”"],
  a:[0], e:"Few-shot: 2 to 4 examples aimed at ambiguous situations, with reasons; contrast acceptable patterns with real problems; and show the variation in document structure (inline citations versus a reference list, for instance)." },
{ id:'ccarf-4-27', d:4, o:2, q:"There are several extraction schemas, and the type of each incoming document is not known in advance. Which `tool_choice` setting fits?",
  c:["`\"any\"`: it must call one of the tools, and the model picks which", "`\"auto\"`: the model decides between calling a tool and replying in text", "`{\"type\":\"tool\",\"name\":\"extract_invoice\"}`: force the commonest type", "`\"none\"`: no tools; first have it state the document type as text"],
  a:[0], e:"When a particular extraction must always run before enrichment, force the named tool, as in {\"type\":\"tool\",\"name\":\"extract_metadata\"}." },
{ id:'ccarf-4-28', d:4, o:3, q:"In invoice extraction you want to catch the error “the line items do not add up to the total”. Which self-correcting design fits?",
  c:["Extract `stated_total` (the document's total) and `calculated_total` (sum of the lines) side by side, detecting a mismatch with `conflict_detected`", "Make `total` a required number in the JSON schema, and treat the total as correct once schema validation passes, since valid syntax covers meaning", "Run the extraction twice and accept `total` when the two runs agree; non-determinism exposes semantic errors, so no validation logic is needed", "Make the `total` field nullable and have null returned when it does not match the lines, the same idea that is used to prevent fabrication"],
  a:[0], e:"Tool use with a JSON schema prevents only syntax errors. Semantic errors (totals that do not match, swapped fields) are found by validation logic." },
{ id:'ccarf-4-29', d:4, o:3, q:"Some extractions are not fixed even by retrying with the validation error attached. In which situation does a retry not help?",
  c:["The information needed is simply not in the source document (it is only in another one)", "The structure of the output JSON differs from the structure of the expected schema", "Dates are not in ISO 8601 form, and the way that they are written varies from item to item", "A required field has come back empty, with no value having been entered into it at all"],
  a:[0], e:"A retry with errors includes the original document, the failed extraction and the specific validation errors. It works on errors of format and structure, but information that is not in the document will never come out." },
{ id:'ccarf-4-30', d:4, o:4, q:"Document results must be returned within 30 hours. Using the Message Batches API (up to 24 hours), which submission interval follows the right reasoning?",
  c:["Every 4 hours. A document may wait at most 6 hours for submission, and the worst case of 4 + 24 = 28 hours fits", "Every 24 hours. Submitting once a day is enough; the worst case is 24 hours, which leaves room inside the SLA", "Every 30 hours. Submitting at the same interval as the SLA wastes nothing, and the worst case is 30 hours", "Every hour. Shorter is always safer, and batch cost depends on the item count, so the interval costs nothing"],
  a:[0], e:"Work back from the SLA to the submission interval. On failure, identify just those documents by custom_id and resubmit them; do not redo the whole batch." },
{ id:'ccarf-4-31', d:4, o:4, q:"Which is a real constraint of the Message Batches API?",
  c:["Within one request, multi-turn tool calling is not possible (a tool cannot be run midway and its result returned)", "One batch may hold only requests that share the same prompt, so the prompt cannot be varied document by document", "Results come back in the order in which they were submitted, and a `custom_id` cannot be attached to requests", "There is an SLA that processing always ends within 1 hour, with automatic failover to the synchronous API if late"],
  a:[0], e:"50% lower cost, up to 24 hours with no SLA, matching by custom_id, completion checked by polling. It suits work that can wait (overnight reports, weekly audits). Work that waits on the result, like a pre-merge check, uses the synchronous API." },
{ id:'ccarf-4-32', d:4, o:5, q:"Having the same session review its own change does not cure the oversights. Which explanation is correct?",
  c:["The model retains its reasoning from generation, so within one session it rarely doubts its own decisions. Have an independent instance without that reasoning do the review", "With extended thinking switched on, the same session catches oversights as well as an independent instance does. A second instance doubles the cost, so it is best avoided", "Strengthen the self-review instruction to “be strict, be critical, and question your own assumptions”, and the same session will then find the problems well enough by itself", "Do not leave review to the model; a person must always look at everything. Model review is pulled along by the reasoning from generation, so it is of no use even as a reference"],
  a:[0], e:"An independent review instance catches problems that self-review instructions and extended thinking do not. Have a confidence attached to each finding to tune the routing." },
{ id:'ccarf-5-25', d:5, o:0, q:"Summarizing a long support conversation in stages, the refund amount and order number became vague. Which response fits?",
  c:["Create a “case facts” block: keep amounts, dates, order numbers and statuses outside the history being summarized, and include it in every prompt", "Stop summarizing and send the whole conversation history every time. Do not summarize until the context limit is hit, then start a new session", "Add the instruction “do not drop the numbers” at each summary, and double the summary length. If the summary is long, the numbers will survive", "Ask the customer again for amounts and order numbers each time they are needed. Not relying on history is more accurate and avoids the issue"],
  a:[0], e:"The risk of progressive summarization is that figures, percentages, dates and customer expectations get rounded off. With several issues, keep the data for each as its own layer. Trim tool output to the relevant fields before it accumulates." },
{ id:'ccarf-5-26', d:5, o:1, q:"Which escalation trigger for a support agent is unreliable?",
  c:["The customer's sentiment (anger, frustration) and the model's self-reported confidence", "The customer having asked, in so many words, to be handled by a human agent", "An exception or gap in policy that cannot be settled on the agent's own judgment", "No meaningful progress being made, with the same exchange being repeated"],
  a:[0], e:"Sentiment and self-reported confidence do not reflect how complex the case really is. If the customer is unhappy but the problem is simple, acknowledge the frustration and offer the fix." },
{ id:'ccarf-5-27', d:5, o:1, q:"The result of `get_customer` matched more than one customer. Which response fits?",
  c:["Do not guess; ask for further identifying information", "Pick the customer who ordered most recently, and carry on", "Escalate the case to a human agent straight away", "Look up both customers' orders, and pick whichever fits"],
  a:[0], e:"Resolve ambiguity before escalating. Cases where policy is ambiguous, or requests policy does not cover (matching a competitor's price), are escalated." },
{ id:'ccarf-5-28', d:5, o:2, q:"When the search subagent times out, which way of responding is the bad pattern?",
  c:["Returning an empty result as a success. The coordinator reads it as “nothing matched” and concludes wrongly", "Returning, as structure, the failure type, the queries tried, partial results and an alternative way forward", "Retrying on the spot and, if that does not resolve it, passing it up with partial results and what was tried", "Annotating the synthesis output with the areas where a source was unavailable and coverage has gaps"],
  a:[0], e:"The other bad pattern is stopping the whole workflow for one failure, which throws away partial work. Tell an access failure apart from “nothing matched”." },
{ id:'ccarf-5-29', d:5, o:3, q:"In a long exploration session, Claude began referring to “typical patterns” and not the specific class names it had found earlier. Which reading and response are correct?",
  c:["A sign of context degradation. Record key findings in a scratchpad file for it to refer to, and delegate specific questions to subagents", "A good sign the model has learned to generalize. Carry on and use the abstract account in design docs; class names can be found by Grep later", "A sign the model tier is too low. A higher model will keep remembering specific class names and stay consistent over a long session", "A sign the codebase is too big. Stop exploring and have a person write a summary; a model cannot be expected to explore a large codebase"],
  a:[0], e:"Crash recovery: each agent writes its state to a fixed location, and on resume the coordinator loads a manifest and puts the state into each request." },
{ id:'ccarf-5-30', d:5, o:4, q:"An extraction pipeline has 97% overall accuracy. May high-confidence extractions be automated, with no human review?",
  c:["Not yet. Overall accuracy hides weak segments, so check accuracy by document type and by field, and keep measuring the error rate of high-confidence extractions by stratified random sampling", "Yes. 97% is high enough, and the remaining 3% can be put right when customers get in touch about them. Human reviewers should then concentrate on handling those enquiries about the remaining 3%", "Yes, and it is safe so long as it is limited to items where the model's self-reported confidence is 90% or more. The model knows its own confidence best, so that threshold can be used just as it stands", "Not yet. People review every item until accuracy reaches 100%. It is safest to begin automating only once errors have fallen to zero, and confidence scores should not be treated even as a reference"],
  a:[0], e:"Have confidence output per field, and calibrate the review threshold on a labeled validation set. Send to people the extractions with low confidence and those whose source document is ambiguous or contradictory." },
{ id:'ccarf-5-31', d:5, o:5, q:"Two credible sources disagree on a statistic. What handling is expected of the document analysis subagent?",
  c:["Keep both conflicting values, annotated with their sources, and let the coordinator decide how to reconcile", "Adopt the value from the newer source and discard the older one, on the view that newer means more correct", "Average the two values into a single figure, and list both of the sources side by side as its origin", "The subagent picks whichever it judges correct on its own, and passes that on without stating a reason"],
  a:[0], e:"Do not pick one arbitrarily. Require publication and data collection dates, so a difference in time is not taken for a contradiction. Established and contested findings go in separate sections." },
];
